/* FallSafe+ Report Generator — station PDF parser
 * Converts the FallSafe+ station result PDFs (generated by the FallSafe+ pipeline)
 * into structured JSON. Works in the browser (pdf.js) and in Node for testing.
 */
(function (root) {
  'use strict';
  const FS = (root.FS = root.FS || {});

  /* ---------- Station registry ---------- */
  const STATIONS = {
    FSST:     { file: /_FSST\b/i,            head: /FSST Results|Four Square/i },
    EMG_DB:   { file: /_EMG_DB\b/i,          head: /Dynamic Balance EMG/i },
    EMG_TTT:  { file: /_EMG_TTT\b/i,         head: /Terrain Trek.*EMG/i },
    BLAZEPOD: { file: /_BLAZE ?POD\b/i,      head: /BlazePod Results/i },
    MVC:      { file: /_MVC\b/i,             head: /MVC Leg Strength/i },
    STS:      { file: /_STS\b/i,             head: /Sit-to-Stand Results|Sit to Stand Results/i },
    TUG:      { file: /_TUG\b/i,             head: /TUG Results|Timed Up/i },
    MMSE:     { file: /_MMSE\b/i,            head: /MMSE Results/i }
  };
  FS.STATION_KEYS = ['FSST', 'EMG_DB', 'EMG_TTT', 'BLAZEPOD', 'STS', 'TUG', 'MVC', 'MMSE'];

  /* ---------- Text extraction (pdf.js) ---------- */
  // Groups pdf.js text items into visual lines, joining cells with " | ".
  FS.extractLines = async function (pdfDoc) {
    const out = [];
    for (let p = 1; p <= pdfDoc.numPages; p++) {
      const page = await pdfDoc.getPage(p);
      const content = await page.getTextContent();
      const rows = [];
      for (const it of content.items) {
        if (!it.str || !it.str.trim()) continue;
        const y = Math.round(it.transform[5]);
        let r = rows.find(r => Math.abs(r.y - y) <= 3);
        if (!r) { r = { y, items: [] }; rows.push(r); }
        r.items.push({ x: it.transform[4], w: it.width || 0, s: it.str });
      }
      rows.sort((a, b) => b.y - a.y);
      for (const r of rows) {
        r.items.sort((a, b) => a.x - b.x);
        // merge items that touch (same cell) and separate distant ones with a pipe
        let line = '', lastEnd = null;
        for (const it of r.items) {
          if (lastEnd === null) line = it.s;
          else line += (it.x - lastEnd > 12 ? ' | ' : (it.x - lastEnd > 1.5 ? ' ' : '')) + it.s;
          lastEnd = it.x + it.w;
        }
        out.push(line.replace(/\s+/g, ' ').trim());
      }
    }
    return out;
  };

  /* ---------- Helpers ---------- */
  const num = s => {
    if (s === undefined || s === null) return null;
    const m = String(s).replace(/,/g, '').match(/-?\d+(?:\.\d+)?/);
    return m ? parseFloat(m[0]) : null;
  };
  FS.num = num;

  function isSpacedHeader(line) {
    const t = line.replace(/\s\|\s/g, ' ').trim();
    const toks = t.split(' ');
    return toks.length >= 4 && toks.filter(x => x.length === 1).length / toks.length > 0.85 && /[A-Z]/.test(t);
  }

  function buildKV(lines) {
    const kv = {}; const after = {}; let section = '';
    let stop = false;
    for (let i = 0; i < lines.length; i++) {
      const ln = lines[i];
      if (/^Reference Norms/i.test(ln) || /^Score 0-10/i.test(ln)) stop = true;
      if (stop) continue;
      if (/generated automatically|^Page \d|^FallSafe\+ \||^Name\s*:/i.test(ln)) continue;
      if (isSpacedHeader(ln)) { section = ln.replace(/[\s|]/g, '').toUpperCase(); continue; }
      if (ln.includes(' | ')) {
        const parts = ln.split(' | ');
        const label = parts[0].trim(); const value = parts.slice(1).join(' ').trim();
        kv[section + '::' + label] = value;
        if (!(label in kv)) kv[label] = value;
      } else {
        const nxt = lines[i + 1];
        if (nxt !== undefined && !(ln in after)) after[ln] = nxt;
      }
    }
    return { kv, after };
  }

  function makeGetter(lines) {
    const { kv, after } = buildKV(lines);
    const stopAt = lines.findIndex(l => /^Reference Norms/i.test(l) || /^Score 0-10/i.test(l));
    const text = (stopAt > 0 ? lines.slice(0, stopAt) : lines).join('\n');
    const get = (label, section) => {
      if (section) {
        const key = Object.keys(kv).find(k => k.startsWith(section.toUpperCase()) && k.endsWith('::' + label));
        if (key) return kv[key];
      }
      if (label in kv) return kv[label];
      // fallback: regex on raw text ("Label 12.3" or "Label: 12.3")
      const re = new RegExp('^' + label.replace(/[.*+?^${}()|[\]\\]/g, '\\$&') + '\\s*[:|]?\\s*(.+)$', 'mi');
      const m = text.match(re);
      return m ? m[1].trim() : undefined;
    };
    const n = (label, section) => num(get(label, section));
    return { get, n, after, text, kv };
  }

  /* ---------- Header / client meta ---------- */
  function parseMeta(lines, filename) {
    const meta = { name: null, age: null, sex: null, heightCm: null, weightKg: null, date: null, time: null, subjectId: null };
    const head = lines.find(l => /^FallSafe\+/.test(l));
    if (head) {
      const m = head.match(/(\d{1,2} [A-Za-z]{3} \d{4}),?\s*(\d{1,2}:\d{2})?/);
      if (m) { meta.date = m[1]; meta.time = m[2] || null; }
    }
    const nl = lines.find(l => /^Name\s*:/i.test(l));
    if (nl) {
      const nm = nl.match(/^Name\s*:\s*([^|·]+?)\s*(\||·|$)/i); if (nm) meta.name = nm[1].trim();
      const a = nl.match(/(\d+)\s*yrs/i); if (a) meta.age = +a[1];
      const s = nl.match(/\b(Male|Female)\b/i); if (s) meta.sex = s[1][0].toUpperCase() + s[1].slice(1).toLowerCase();
      const h = nl.match(/([\d.]+)\s*cm/i); if (h) meta.heightCm = +h[1];
      const w = nl.match(/([\d.]+)\s*kg/i); if (w) meta.weightKg = +w[1];
    }
    const fm = (filename || '').match(/^(.+?)_(\d{6,})_(Male|Female)_(\d{1,3})/i);
    if (fm) {
      meta.subjectId = `${fm[1]}_${fm[2]}_${fm[3]}_${fm[4]}`;
      meta.name = meta.name || fm[1];
      meta.sex = meta.sex || (fm[3][0].toUpperCase() + fm[3].slice(1).toLowerCase());
      meta.age = meta.age || +fm[4];
    }
    return meta;
  }

  /* ---------- Station detection ---------- */
  FS.detectStation = function (filename, lines) {
    const base = (filename || '').replace(/\.pdf$/i, '');
    for (const k of FS.STATION_KEYS) if (STATIONS[k].file.test(base)) return k;
    const head = (lines || []).slice(0, 4).join(' ');
    for (const k of FS.STATION_KEYS) if (STATIONS[k].head.test(head)) return k;
    return null;
  };

  /* ---------- Station parsers ---------- */
  const P = {};

  P.FSST = g => ({
    riskLabel: g.after['Fall Risk'] || null,
    timeS: g.n('Time to Complete'),
    agility: g.n('Agility Score'),
    stability: g.n('Stability Score'),
    avgStepDurS: g.n('Avg Step Duration'),
    stepCVpct: g.n('Step Variability CV'),
    stepVarS: g.n('Step Variability'),
    stepLenMean: g.n('Step Length (mean)'),
    stepLenL: g.n('Step Length (left)'),
    stepLenR: g.n('Step Length (right)'),
    stepWidth: g.n('Step Width (mean)'),
    dsiPct: g.n('Directional Symmetry'),
    interlimbS: g.n('Inter-limb Coordination'),
    peakTrunkDeg: g.n('Peak Trunk Angle'),
    meanTrunkVel: g.n('Mean Trunk Ang. Velocity'),
    doubleSupportPct: g.n('Double-Support Ratio'),
    nearFall: /detect|yes|true/i.test(g.get('Near-Fall Event') || '') ? true : (/none|no|false|not/i.test(g.get('Near-Fall Event') || '') ? false : null),
    instability: g.n('Instability Score'),
    cwS: g.n('Clockwise (stages 1-4)'),
    acwS: g.n('Anti-clockwise (stages 5-8)'),
    phaseRatio: num((Object.entries(g.kv).find(([k]) => /Phase Ratio/i.test(k)) || [])[1]),
    hesitations: g.n('Hesitations'),
    lineTouches: g.n('Line Touches'),
    seqErrors: g.n('Sequence Errors')
  });

  function emg(g) {
    const ds = Object.keys(g.after).find(k => /^(Dynamic Balance|Static Balance|Terrain|Proprioception|Coordination)/i.test(k) && /\/\s*100/.test(g.after[k]));
    const ch = lab => {
      const v = g.get(lab, 'CHANNELQUALITY') || '';
      return { snr: num((v.match(/SNR:\s*(-?[\d.]+)/i) || [])[1]), rms: num((v.match(/RMS:\s*(-?[\d.]+)/i) || [])[1]) };
    };
    const mvc = lab => num(g.get(lab, 'MVC'));
    const sub = {};
    Object.keys(g.kv).filter(k => k.startsWith('SUB-METRICS::') || k.startsWith('SUBMETRICS::')).forEach(k => { sub[k.split('::')[1]] = num(g.kv[k]); });
    const note = g.get('Note') || '';
    return {
      domainLabel: ds || null,
      composite: ds ? num(g.after[ds]) : null,
      sub,
      nSamples: g.n('N Samples'), durationS: g.n('Duration S'), nFeatures: g.n('N Features'),
      ch: { LQ: ch('Left Quad'), RQ: ch('Right Quad'), LC: ch('Left Calf'), RC: ch('Right Calf') },
      calfSym: g.n('Calf Symmetry Ratio'),
      quadSym: g.n('Quad Symmetry Ratio'),
      coactL: g.n('Left Coactivation Index'),
      coactR: g.n('Right Coactivation Index'),
      quadCalf: g.n('Quad-Calf Ratio'),
      actFrac: g.n('Activation Fraction'),
      terrainCV: g.n('Terrain Adaptation Cv 30W') ?? g.n('Terrain Adaptation CV'),
      mvcPct: { LQ: mvc('Left Quad'), RQ: mvc('Right Quad'), LC: mvc('Left Calf'), RC: mvc('Right Calf') },
      mvcNotCollected: /not collected/i.test(note + ' ' + g.text)
    };
  }
  P.EMG_DB = emg; P.EMG_TTT = emg;

  P.BLAZEPOD = g => ({
    score: num(g.after['Reaction Score']),
    percentile: num((g.get('Peer Percentile') || '').match(/(\d+(?:\.\d+)?)\s*%/)?.[1]),
    peerNormMs: g.n('Peer Norm (mean RT)'),
    riskBand: g.get('Risk Band') || null,
    avgRtMs: g.n('Avg Reaction Time Ms') ?? g.n('Avg Reaction Time'),
    medianRtMs: g.n('Median Rt Ms') ?? g.n('Median RT'),
    rtCV: g.n('Rt Cv'),
    hits: g.n('Total Hits'),
    misses: g.n('Total Misses'),
    accuracyPct: g.n('Accuracy Pct') ?? g.n('Accuracy'),
    cuesAfter: g.n('Cues After Filtering'),
    outliers: g.n('Outlier Cues Removed')
  });

  P.MVC = g => {
    const l = g.get('Left MVC') || '', r = g.get('Right MVC') || '';
    const pct = s => num((s.match(/(\d+(?:\.\d+)?)\s*(?:st|nd|rd|th)\s*percentile/i) || [])[1]);
    const ca = g.get('Calf Asymmetry') || '';
    return {
      status: g.after['Symmetry Status'] || null,
      asymPct: g.n('Asymmetry'),
      leftKg: num(l), rightKg: num(r), leftPctile: pct(l), rightPctile: pct(r),
      leftTrials: g.get('Left Trials (kg)'), rightTrials: g.get('Right Trials (kg)'),
      calfStatus: ca.replace(/\(.*\)/, '').trim() || null,
      calfAsymPct: num((ca.match(/\(([\d.]+)%\)/) || [])[1]),
      leftCalfKg: g.n('Left Calf MVC'), rightCalfKg: g.n('Right Calf MVC'),
      kneeAngle: g.n('Knee Angle'), hurModel: g.get('HUR Model') || null, protocol: g.get('Protocol') || null
    };
  };

  P.STS = g => ({
    reps: g.n('Total Repetitions'),
    durationS: g.n('Total Duration'),
    peakVel: g.n('Peak Standing Vertical Velocity'),
    trans: { avg: g.n('Average', 'TRANSITION'), min: g.n('Minimum', 'TRANSITION'), max: g.n('Maximum', 'TRANSITION'), sd: g.n('Std Deviation', 'TRANSITION') },
    stand: { avg: g.n('Average', 'STANDING'), sd: g.n('Std Deviation', 'STANDING') },
    hip: { seated: g.n('Seated', 'HIP'), transition: g.n('Transition', 'HIP'), standing: g.n('Standing', 'HIP') },
    trunk: { seated: g.n('Seated', 'TRUNK'), transition: g.n('Transition', 'TRUNK'), standing: g.n('Standing', 'TRUNK') },
    hipSym: g.n('Hip Symmetry Ratio')
  });

  P.TUG = g => ({
    riskLabel: g.after['Fall Risk'] || null,
    probabilityPct: g.n('Probability'),
    timeS: g.n('TUG Duration'),
    gaitVel: g.n('Gait Velocity'),
    strideLen: g.n('Avg Stride Length'), strideTime: g.n('Avg Stride Time'),
    strideLenL: g.n('Left Stride Length'), strideTimeL: g.n('Left Stride Time'),
    strideLenR: g.n('Right Stride Length'), strideTimeR: g.n('Right Stride Time'),
    sitToStandS: g.n('Seated to Full Extension'), aroundConeS: g.n('Time Around Cone'),
    turnToSitS: g.n('Turn to Sit'), toSitS: g.n('Time to Sitting Down'),
    firstFoot: g.get('First Foot Walk') || null, lastFoot: g.get('Last Foot Walk') || null
  });

  P.MMSE = g => {
    const tot = g.after['MMSE Score'] || g.get('MMSE Score') || '';
    const m = tot.match(/(\d+(?:\.\d+)?)\s*\/\s*(\d+)/);
    const dom = lab => { const v = g.get(lab) || ''; const x = v.match(/(\d+(?:\.\d+)?)\s*\/\s*(\d+)/); return x ? { score: +x[1], max: +x[2] } : null; };
    const qs = [];
    for (let i = 1; i <= 30; i++) { const v = g.n('Question ' + i); if (v === null) break; qs.push(v); }
    return {
      total: m ? +m[1] : null, totalMax: m ? +m[2] : null,
      label: (tot.split(' - ')[1] || '').trim() || null,
      timeMs: g.n('Total Time Taken'),
      domains: { orientation: dom('Orientation'), registration: dom('Registration'), attention: dom('Attention'), recall: dom('Recall'), language: dom('Language') },
      questions: qs
    };
  };

  /* ---------- Public: parse one PDF ---------- */
  FS.parseLines = function (lines, filename) {
    const station = FS.detectStation(filename, lines);
    if (!station) return { ok: false, filename, error: 'unrecognised' };
    const g = makeGetter(lines);
    let data;
    try { data = P[station](g); } catch (e) { return { ok: false, filename, station, error: e.message }; }
    return { ok: true, filename, station, meta: parseMeta(lines, filename), data };
  };

  FS.parsePdfFile = async function (file, pdfjsLib) {
    const buf = new Uint8Array(await file.arrayBuffer());
    const doc = await pdfjsLib.getDocument({ data: buf }).promise;
    const lines = await FS.extractLines(doc);
    return FS.parseLines(lines, file.name);
  };
})(typeof window !== 'undefined' ? window : globalThis);
